Future<Uint8List> cardBytes(String num,Pkg pkg)async{final rec=ui.PictureRecorder();final cv=Canvas(rec);const w=576.0,h=380.0;cv.drawRect(Rect.fromLTWH(0,0,w,h),Paint()..color=Colors.white);
